    git: <><circle cx="7" cy="5" r="2" /><circle cx="7" cy="19" r="2" /><circle cx="18" cy="6" r="2" /><path d="M7 7v10m11-9c0 6-11 3-11 8" /></>,
    environment: <><rect x="3" y="4" width="18" height="13" rx="2" /><path d="M8 21h8m-4-4v4M7 8l3 3-3 3m6 0h4" /></>,
    plugins: <><path d="M9 3v4H5v5h4v4h5v5h5v-5h2v-5h-7V7H9V3Z" /></>,
    computer: <><rect x="3" y="4" width="18" height="13" rx="2" /><path d="M8 21h8m-4-4v4m2-12 2 6 1-3 3-1z" /></>,
