+.field-label { display: grid; gap: 7px; color: var(--color-text-secondary); font-size: 11px; margin-bottom: 16px; }
+.field-label input, .field-label select, .search input, .connect-controls input { width: 100%; min-width: 0; border: 1px solid var(--color-border); border-radius: 7px; background: var(--app-color-background-control); color: var(--color-text); padding: 9px 10px; outline: 0; }
+.search { display: flex; gap: 8px; margin-bottom: 16px; }
+.button { border: 1px solid var(--color-border); background: var(--app-color-background-control); color: var(--color-text); border-radius: 7px; padding: 8px 11px; font-size: 11px; white-space: nowrap; }
+.button:hover { background: var(--color-background-secondary-ghost-hover); }
+.button.primary { background: var(--color-text); border-color: var(--color-text); color: var(--app-color-background-surface); font-weight: 500; }
+.button-row { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 12px; }
+.connect-banner { display: flex; gap: 16px; align-items: center; justify-content: space-between; background: var(--app-color-background-surface-under); border-bottom: 1px solid var(--color-border-subtle); padding: 14px 26px; }
