Set-Content -LiteralPath $forgeCssPath -Value ($forgeTokens + "`n" + $forgeExtensions + "`n" + $forgeLegacyCss + "`n" + $forgeSkeleton) -Encoding utf8

parsed_cmd.cmd:
$forgeCssPath = 'D:\Competition_this\Agent\desktop\src\style.css'
$forgeLegacyCss = Get-Content -LiteralPath $forgeCssPath -Raw
$forgeTokens = Get-Content -LiteralPath 'D:\crack\chatgpt-ui\design\forge-tokens.css' -Raw
$forgeTokens = $forgeTokens -replace '(?m)^\s*--(?:user-message-background-color|user-message-text-color|color-text-chat-accent-blue):[^\r\n]*\r?\n', ''
$forgeTokens = $forgeTokens.Replace('color-mix(in oklab, #0d0d0d 5%, transparent)', 'rgba(13, 13, 13, 0.05)').Replace('color-mix(in oklab, #fcfcfc 5%, transparent)', 'rgba(252, 252, 252, 0.05)')
$forgeLegacyCss = $forgeLegacyCss -replace '^:root\{[^}]*\}', ''
$forgeLegacyCss = [regex]::Replace($forgeLegacyCss, '#[a-fA-F0-9]{3,8}\b', {
  param($match)
  $value = $match.Value.ToLowerInvariant()
  if ($value -eq '#fff') { return 'var(--app-color-background-surface)' }
  if ($value -in @('#a24740', '#a44b44')) { return 'var(--color-status-error)' }
  if ($value -in @('#966a36', '#9a713b', '#6f5a3c')) { return 'var(--color-status-warning)' }
  if ($value -eq '#fcf8f1') { return 'var(--color-background-warning)' }
  if ($value -eq '#e3d5bf') { return 'var(--color-border-warning)' }
  if ($value.StartsWith('#000000')) { return 'var(--color-shadow-soft)' }
  if ($value -in @('#526b80', '#526f89', '#667c8f')) { return 'var(--color-text-accent)' }
  if ($value -eq '#667f91') { return 'var(--color-accent)' }
  if ($value -match '^#[def][0-9a-f]{5}$') { return 'var(--color-border)' }
  if ($value -match '^#f[0-9a-f]{5}$') { return 'var(--app-color-background-surface-under)' }
  if ($value -in @('#333', '#202326', '#202226', '#202428', '#292c2f', '#17191b', '#24272a', '#303438', '#30363b', '#333b42')) { return 'var(--color-text)' }
  return 'var(--app-color-text-foreground-tertiary)'
})
$forgeLegacyCss = $forgeLegacyCss.Replace('}', "}`n").Replace('{', " {`n  ").Replace(';', ";`n  ")
$forgeExtensions = @'
/* FORGE semantic extensions: statuses and surfaces outside the captured subset.
   Static system fonts approximate captured 430 / 510 weights with 400 / 500. */
:root {
  --color-text-secondary: rgba(13, 13, 13, .72);
  --color-background-nav-active: rgba(13, 13, 13, .055);
  --color-background-control-subtle: rgba(13, 13, 13, .03);
  --color-border-strong: rgba(13, 13, 13, .118);
  --color-background-command: rgba(13, 13, 13, .055);
  --color-status-error: #a24740;
  --color-status-warning: #966a36;
  --color-background-warning: #fcf8f1;
  --color-border-warning: #e3d5bf;
  --color-scrollbar: rgba(13, 13, 13, .18);
  --color-shadow-soft: rgba(0, 0, 0, .04);
  --color-mask-solid: #000000;
  --muted: var(--app-color-text-foreground-tertiary);
  --line: var(--color-border);
  --accent: var(--color-accent);
}
[data-theme="dark"] {
  --color-text-secondary: rgba(252, 252, 252, .72);
  --color-background-nav-active: rgba(252, 252, 252, .078);
  --color-background-control-subtle: rgba(252, 252, 252, .04);
  --color-border-strong: rgba(252, 252, 252, .14);
  --color-background-command: rgba(252, 252, 252, .055);
  --color-status-error: #ff9c94;
  --color-status-warning: #e0b471;
  --color-background-warning: #2a241b;
  --color-border-warning: #66523c;
  --color-scrollbar: rgba(252, 252, 252, .22);
}
:root {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "Microsoft YaHei", var(--font-sans), Inter, sans-serif;
  color: var(--color-text);
  background: var(--app-color-background-surface-under);
  font-weight: 400;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}
