  </div>;
}

function EventLine({ event, onQuest, onInspect }: { event: TimelineEvent; onQuest: (id: string) => void; onInspect: () => void }) {
  const detail = event.detail && typeof event.detail === "object" && !Array.isArray(event.detail) ? event.detail as Row : {};
  const target = typeof detail.path === "string" ? detail.path : typeof detail.command === "string" ? detail.command : "";
  const failed = event.status === "failed" || event.status === "worker.failed" || event.status === "tool.execution_uncertain" || (typeof detail.exit_code === "number" && detail.exit_code !== 0);
  const unknown = event.status === "unknown" || event.status === "uncertain" || event.status === "tool.execution_uncertain";
  return <details onToggle={onInspect} className={`event-line${failed ? " failed" : ""}${unknown ? " unknown" : ""}`}><summary><ActivityIcon /><span className="event-label">{target || eventTitle(event)}{(failed || unknown) && <span className="event-failed"> · {unknown ? "结果未知" : "失败"}{typeof detail.exit_code === "number" ? `（退出码 ${detail.exit_code}）` : ""}</span>}{event.execution_mode === "mock" && <small className="event-mode"> · 模拟</small>}</span><Chevron /></summary>
    <div className="event-detail">
      {typeof detail.command === "string" && <CommandCard detail={detail} onInspect={onInspect} />}
      {["file_write", "file_revise"].includes(text(detail.tool, "")) && typeof detail.path === "string" && <div className="resource-card"><span className="resource-icon" aria-hidden="true"><ActivityIcon /></span><span><strong>{detail.path}</strong><small>{eventTitle(event)}</small></span></div>}
      <p>{event.execution_mode === "live" ? "真实执行" : event.execution_mode === "mock" ? "模拟" : "来源未知"} · {event.created_at ? new Date(event.created_at).toLocaleString() : "时间未知"}</p>{event.quest_id && <button className="text-button" onClick={() => onQuest(event.quest_id!)}>查看关联任务</button>}<dl>{Object.entries(detail).map(([key, value]) => <div key={key}><dt>{({ path: "路径", tool: "工具", result_sha256: "结果摘要", command: "命令", exit_code: "退出码", scope: "范围", source_count: "来源数" } as Record<string, string>)[key] || key}</dt><dd>{text(value)}</dd></div>)}</dl><small>记录 ID：{event.event_id}</small>
    </div></details>;
}

function EventGroup({ item, onQuest, onInspect }: { item: Extract<DisplayItem, { type: "group" }>; onQuest: (id: string) => void; onInspect: () => void }) {
  const summary = [...new Set(item.events.map(eventTitle))].join("");
  return <details className="event-group" onToggle={onInspect}><summary aria-label={item.events.length > 2 ? `查看较早的 ${item.events.length - 2} 条${item.questId ? "任务记录" : "后台活动"}` : undefined}><ActivityIcon /><span className="event-label">{summary}</span><Chevron /></summary>
