}
.command-no-output { margin: 0; padding: 8px; color: var(--muted); font-size: 12px; line-height: 16px; }
.message.from-agent .markdown { font-size: 16px; line-height: 24px; font-weight: 400; }
.message.from-user .markdown { font-size: 14px; line-height: 21px; }
.send-button:disabled { opacity: 1; background: var(--color-background-secondary-ghost-hover); color: var(--muted); }
.action-error { width: 100%; max-width: var(--thread-content-max-width); margin: 0 auto 8px; padding: 0 24px; }

@media (max-width: 1100px) {
