}
@media (max-width: 760px) {
  .nav-icon { width: 16px; height: 16px; }
  .timeline { min-height: 0; padding: 24px 24px 120px; }
  .composer-wrap { padding: 0 24px 20px; }
  .connect-banner { align-items: stretch; flex-direction: column; padding: 14px 20px; }
  .connect-controls { min-width: 0; }
  .empty-conversation { margin: 10vh auto; }
  .settings-content .settings-row-control, .settings-content .field-label input,
  .settings-content .field-label select, .settings-content .field-label textarea { max-width: 100%; min-width: 0; }
  .event-detail dl > div { flex-wrap: wrap; }
}
@media (hover: none) {
  .message .message-meta, .code-toolbar button, .copy-btn, .event-line .actions { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: .01ms !important;
    animation-duration: .01ms !important;
    scroll-behavior: auto !important;
  }
}

