    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2" target="_blank" rel="noreferrer" class="underline decoration-1 underline-offset-2">$1</a>');

  const lines = text.split('\n');
  const out = [];
  let list = null;
  let para = [];
  let codeBlock = null;

  const flushPara = () => {
    if (para.length) { out.push(`<p class="Paragraph-kKnbIo">${inline(para.join(' '))}</p>`); para = []; }
