/* Minimal glue so the real stylesheet drives a static, data-bound app. */

html, body {
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--color-background-primary, #fff);
  color: var(--color-text, #0d0d0d);
  font-family: var(--font-sans, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif);
}

#root { height: 100%; }
#shell { height: 100%; }

/* the app's PageSurface normally comes from its own layout component */
#page-surface {
  min-width: 0;
  position: relative;
}

/* home view: the extracted home layout is height-driven; give it room */
#home-view { min-height: 0; }
#home-view > .contents > .contents { height: 100%; }

/* thread view */
#thread-view { min-height: 0; }
#transcript { min-height: 0; }

/* sidebar keeps its own width; avoid the app's responsive collapse fighting us */
aside.app-shell-left-panel { flex: 0 0 auto; order: -1; }

/* contenteditable placeholder support (the app's ProseMirror normally does this) */
[contenteditable="true"]:empty::before,
[contenteditable="true"] p[data-placeholder]::before {
  content: attr(data-placeholder);
  color: var(--color-text-tertiary, #8f8f8f);
  pointer-events: none;
}

[contenteditable="true"] { outline: none; }

/* markdown spacing inside messages */
.MarkdownRoot-rZKhxa > * + * { margin-top: 0.75em; }
.MarkdownRoot-rZKhxa pre { max-width: 100%; }
.MarkdownRoot-rZKhxa table { border-collapse: collapse; }
.MarkdownRoot-rZKhxa th,
.MarkdownRoot-rZKhxa td { border: 1px solid var(--color-border-subtle, #0002); padding: 4px 8px; }

/* thin scrollbars to match the desktop app */
* { scrollbar-width: thin; }
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, currentColor 18%, transparent);
  border-radius: 6px;
  border: 3px solid transparent;
  background-clip: content-box;
}
::-webkit-scrollbar-track { background: transparent; }

/* hover-reveal action bars need a real hover target */
.group\/user-message:hover .group-hover\/user-message\:opacity-100,
.group\/agent-message:hover .group-hover\/agent-message\:opacity-100,
.group\/turn-diff:hover .group-hover\/turn-diff\:opacity-100 { opacity: 1; }

/* selected thread row */
[data-app-action-sidebar-thread-selected="true"] {
  background: var(--color-background-secondary-ghost-hover, rgb(0 0 0 / 0.06));
}

/* keep the sidebar scroll area usable */
aside .vertical-scroll-fade-mask { overflow-y: auto; }

