import { useState, type ReactNode } from "react";

export type SettingId = "general" | "appearance" | "shortcuts" | "archived" |
  "quests" | "teams" | "memory" | "approvals" | "models" | "activity" |
  "connections" | "git" | "environment" | "plugins" | "computer" | "storage" | "import";

interface SettingItem { id: SettingId; label: string; accessibleLabel?: string }
interface SettingGroup { label: string; items: SettingItem[] }

export const settingGroups: SettingGroup[] = [
  { label: "个人", items: [
    { id: "general", label: "常规" },
    { id: "appearance", label: "外观" },
    { id: "shortcuts", label: "键盘快捷键" },
    { id: "archived", label: "已归档的聊天" },
  ] },
  { label: "工作区", items: [
    { id: "quests", label: "任务", accessibleLabel: "后台任务" },
    { id: "teams", label: "任务团队" },
    { id: "memory", label: "记忆中心" },
    { id: "approvals", label: "审批中心" },
    { id: "models", label: "模型库" },
    { id: "activity", label: "运行活动" },
  ] },
  { label: "集成", items: [
    { id: "connections", label: "连接" },
    { id: "git", label: "Git" },
    { id: "environment", label: "环境" },
    { id: "plugins", label: "插件" },
    { id: "computer", label: "电脑操控" },
  ] },
  { label: "数据", items: [
    { id: "storage", label: "存储" },
    { id: "import", label: "导入" },
  ] },
];

function SettingIcon({ id }: { id: SettingId }) {
  const paths: Record<SettingId, ReactNode> = {
    general: <><circle cx="12" cy="12" r="3" /><path d="M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4m0-12.8L17 7M7 17l-1.4 1.4" /></>,
    appearance: <><circle cx="12" cy="12" r="8" /><path d="M12 4v16M12 4a8 8 0 0 1 0 16Z" /></>,
    shortcuts: <><rect x="3" y="6" width="18" height="12" rx="2" /><path d="M6 10h1m4 0h1m4 0h1M6 14h1m3 0h7" /></>,
    archived: <><path d="M4 8h16v12H4zM3 4h18v4H3zM9 12h6" /></>,
    quests: <><path d="M4 7h6l2 2h8v11H4zM4 7V4h6l2 3" /></>,
    teams: <><circle cx="9" cy="8" r="3" /><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v2" /></>,
    memory: <><path d="m12 3 9 9-9 9-9-9z" /><circle cx="12" cy="12" r="2" /></>,
    approvals: <><path d="m12 3 8 3v6c0 4-3 7-8 9-5-2-8-5-8-9V6zM8 12l3 3 5-6" /></>,
    models: <><rect x="4" y="4" width="6" height="6" rx="1" /><rect x="14" y="4" width="6" height="6" rx="1" /><rect x="4" y="14" width="6" height="6" rx="1" /><rect x="14" y="14" width="6" height="6" rx="1" /></>,
    activity: <><circle cx="12" cy="12" r="9" /><path d="M12 7v5l4 2" /></>,
    connections: <><path d="m10 13 4-4M8 16l-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m4 0 2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0" transform="translate(1 0) scale(.92)" /></>,
    git: <><circle cx="7" cy="5" r="2" /><circle cx="7" cy="19" r="2" /><circle cx="18" cy="6" r="2" /><path d="M7 7v10m11-9c0 6-11 3-11 8" /></>,
    environment: <><rect x="3" y="4" width="18" height="13" rx="2" /><path d="M8 21h8m-4-4v4M7 8l3 3-3 3m6 0h4" /></>,
    plugins: <><path d="M9 3v4H5v5h4v4h5v5h5v-5h2v-5h-7V7H9V3Z" /></>,
    computer: <><rect x="3" y="4" width="18" height="13" rx="2" /><path d="M8 21h8m-4-4v4m2-12 2 6 1-3 3-1z" /></>,
    storage: <><ellipse cx="12" cy="5" rx="8" ry="3" /><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0" /></>,
    import: <><path d="M12 3v12m-4-4 4 4 4-4M4 14v6h16v-6" /></>,
  };
  return <svg className="settings-nav-icon" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[id]}</svg>;
}

export function SettingsRow({ label, description, children }: { label: ReactNode; description?: ReactNode; children: ReactNode }) {
  return <div className="settings-row">
    <div className="settings-row-text"><div className="settings-row-label">{label}</div>{description && <div className="settings-row-desc">{description}</div>}</div>
    <div className="settings-row-control">{children}</div>
  </div>;
}

export default function SettingsView({ selected, onSelect, children }: { selected: SettingId; onSelect: (id: SettingId) => void; children: ReactNode }) {
  const [query, setQuery] = useState("");
  const search = query.trim().toLocaleLowerCase();
  const groups = settingGroups.map((group) => ({ ...group, items: group.items.filter((item) => `${group.label} ${item.label} ${item.accessibleLabel || ""}`.toLocaleLowerCase().includes(search)) })).filter((group) => group.items.length > 0);
  const current = settingGroups.flatMap((group) => group.items).find((item) => item.id === selected)!;
  return <section className="settings-view" aria-label="设置">
    <nav className="settings-nav" aria-label="设置导航">
      <div className="settings-search"><input type="search" aria-label="搜索设置" placeholder="搜索设置" value={query} onChange={(event) => setQuery(event.target.value)} /></div>
      {groups.map((group) => <div className="settings-nav-section" key={group.label}>
        <h2 className="settings-nav-group">{group.label}</h2>
        {group.items.map((item) => <button type="button" key={item.id} className={`settings-nav-item${selected === item.id ? " active" : ""}`} aria-label={item.accessibleLabel} aria-current={selected === item.id ? "page" : undefined} onClick={() => onSelect(item.id)}><SettingIcon id={item.id} /><span>{item.label}</span></button>)}
      </div>)}
      {!groups.length && <p className="notice">未找到匹配的设置</p>}
    </nav>
    <div className="settings-content"><h1 className="settings-title">{current.label}</h1>{children}</div>
  </section>;
}


  const acknowledgeUnknown = async () => {
    if (!native || workspaceOperation?.status !== "unknown" || !workspaceOperation.operationId || !reviewReason.trim() || actionBusy) return;
    if (!window.confirm(`归档未知维护结果 ${workspaceOperation.operationId}？\n请先核对工作区和备份。此操作不表示维护成功，也不会解除恢复锁定或预算限制。`)) return;
    operationPollSerial.current += 1; maintenanceSubmitting.current = true; setActionBusy(true); setActionError("");
    try { setWorkspaceOperation(await invoke<WorkspaceOperation>("workspace_operation_acknowledge", { operationId: workspaceOperation.operationId, reason: reviewReason.trim() })); setReviewReason(""); }
    catch (error) { setActionError(errorMessage(error)); }
    finally { maintenanceSubmitting.current = false; setActionBusy(false); }
  };

  const retryRuntime = async () => {
    if (!native || writesBlocked || actionBusy || !window.confirm("重启本地 Core？正在运行的任务可能中断。")) return;
    setActionBusy(true); setActionError("");
    try { await invoke("runtime_retry"); await syncNative(); }
    catch (error) { setActionError(errorMessage(error)); }
    finally { setActionBusy(false); }
  };

  const plan = visiblePlan.value as Row | null;
  const panelItems = (view === "memory" || view === "approvals") && visiblePanel.value && typeof visiblePanel.value === "object" && !Array.isArray(visiblePanel.value) ? rows((visiblePanel.value as Row).items) :
    view === "activity" && visiblePanel.value && typeof visiblePanel.value === "object" && !Array.isArray(visiblePanel.value) ? rows((visiblePanel.value as Row).items ?? (visiblePanel.value as Row).events) : rows(visiblePanel.value);
  const title = VIEW_NAMES[view];
  const selectSetting = (id: SettingId) => { setSetting(id); setView(SETTING_VIEWS[id] || "settings"); setActionError(""); };
  const decideApproval = (item: Row, decision: "APPROVED" | "REJECTED") => {
    if (window.confirm(`${decision === "APPROVED" ? "批准" : "拒绝"}此操作？\n风险：${text(item.risk)}\n范围：${text(item.resource_scope)}\n计划版本：${text(item.plan_revision)}\n参数摘要：${text(item.parameter_digest)}`)) void perform(`/api/approvals/${encodeURIComponent(text(item.id))}/decision`, { decision, expected_digest: item.parameter_digest, expected_plan_revision: item.plan_revision });
  };
  const grantPanel = (view === "quests" || view === "approvals") && selected && <GrantPanel quest={selected} state={visibleGrants} workspace={grantContext === `${questContextKey}|${view}` ? workspaceRoot : ""} scope={grantScope} setScope={setGrantScope} blocked={actionBusy || writesBlocked} submit={(path, body) => void perform(path, body)} />;

  return <div className={`app-shell${settingsOpen ? " settings-open" : ""}`}>
    <header className="desktop-chrome">
      <div className="desktop-chrome-leading" aria-hidden="true"><span><ShellGlyph name="back" /></span><span><ShellGlyph name="forward" /></span><span><ShellGlyph name="panel" /></span><div className="desktop-menu"><span>文件</span><span>编辑</span><span>视图</span><span>帮助</span></div></div>
      <div className="connection-indicator"><span className={connection ? "status-dot on" : "status-dot"} />{connection ? "Core 已连接" : "Core 未连接"}</div>
    </header>
    <aside className="rail" aria-label="主导航">
      <div className="primary-rail"><nav className="primary-nav">{NAV.map((item) => <button key={item.id} title={item.name} aria-label={item.name} className={!settingsOpen && (view === item.id || (item.id === "quests" && view === "activity")) ? "nav-item active" : "nav-item"} aria-current={!settingsOpen && (view === item.id || (item.id === "quests" && view === "activity")) ? "page" : undefined} onClick={() => { setSettingsOpen(false); setView(item.id); setActionError(""); }}><Icon name={item.id} /><span className="sr-only">{item.label}</span></button>)}</nav>
        <button className="profile-button" aria-label="设置" title="设置 (Ctrl+,)" onClick={openSettings}><Icon name="settings" /></button>
      </div>
      <div className="sidebar-panel">
        <div className="sidebar-heading"><strong>FORGE</strong><ShellGlyph name="chevron" /><span className="sidebar-heading-tools" aria-hidden="true"><ShellGlyph name="bell" /><ShellGlyph name="search" /></span></div>
        <button className="sidebar-new-chat" onClick={() => { setSettingsOpen(false); setView("chat"); requestAnimationFrame(() => document.querySelector<HTMLTextAreaElement>('textarea[aria-label="消息内容"]')?.focus()); }}><ShellGlyph name="compose" /><span>新聊天</span></button>
        <div className="sidebar-scroll"><div className="sidebar-section-title"><span>最近会话</span><ShellGlyph name="search" /></div><button className={view === "chat" && !settingsOpen ? "thread-row active" : "thread-row"} onClick={() => { setSettingsOpen(false); setView("chat"); }}>长期对话</button><div className="sidebar-section-title workspace-section">工作空间</div><div className="sidebar-workspace"><ShellGlyph name="folder" /><span>{connection?.workspace_id || "FORGE"}</span></div></div>
        <div className="sidebar-connection">{!connection && <div className="connect-banner" role="status"><div><strong>{native ? "正在连接本地 Core" : "连接开发 Core"}</strong><p>{native ? "等待桌面运行时提供安全会话。" : "输入本次 Core 启动密钥。密钥不会保存在浏览器中。"}</p>{connectionError && <p className="error">{connectionError}</p>}</div>{!native && <div className="connect-controls"><input ref={secretInput} type="password" autoComplete="off" aria-label="Core 启动密钥" placeholder="本次启动密钥" /><button className="button primary" onClick={() => void connectBrowser()}>连接</button></div>}</div>}</div>
      </div>
    </aside>
    <main className={`conversation-shell${messages.length || timelineEvents.length || outgoing.length ? "" : " home-state"}`} hidden={view !== "chat"}>
      <header className="topbar"><div className="topbar-title"><Icon name="chat" /><h1>长期对话</h1></div><div className="connection-indicator"><span className={connection ? "status-dot on" : "status-dot"} />{connection ? "Core 已连接" : "Core 未连接"}</div></header>
      {writesBlocked && <div className="maintenance-banner" role="status">{restoreFenced === true ? "恢复后写操作已锁定，请先人工核对。" : workspaceOperation?.status === "unknown" && !workspaceOperation.acknowledged ? "维护结果未知，请人工核查；写操作已暂停。" : runtimeStatus?.state === "maintenance" || workspaceOperation?.status === "running" ? "正在备份或恢复，完成后可退出；写操作已暂停。" : "正在核对工作空间恢复状态；写操作暂不可用。"}</div>}
      <ChatTimeline messages={messages} events={timelineEvents} outgoing={outgoing} quests={quests}
        approvals={pendingApprovals} native={native} connected={!!connection} historyMore={hasMore || timelineHasMore}
        historyBusy={historyBusy} timelineError={timelineError} conversationError={conversationError}
        approvalError={approvalLoadError} canRetry={!!connection && !sending && !writesBlocked} scrollRef={scrollRef}
        onScroll={() => { const element = scrollRef.current; if (!element || manualPause.current) return; followBottom.current = isNearBottom(element.scrollTop, element.clientHeight, element.scrollHeight); if (followBottom.current) setHasNew(false); }}
        onInspect={() => { manualPause.current = true; followBottom.current = false; setReadingPaused(true); }}
        onLoadOlder={() => void loadOlder()} onRetry={(item) => void sendPending(item, false)}
        onQuest={(id) => { setSelectedId(id); setView("quests"); }}
        onApproval={(id) => { setSelectedId(id); setSetting("approvals"); setSettingsOpen(true); setView("approvals"); }}
        approvalsBlocked={actionBusy || writesBlocked} onApprovalDecision={decideApproval} />
